        : calendarMonthHasAvailableDate(addCalendarMonths(month, -1), minDate, maxDate)
  const nextAvailable =
    view === 'years'
      ? yearPage + 12 <= 9999 &&
        getCalendarYearPage(yearPage + 12).some((year) =>
          calendarYearHasAvailableDate(year, minDate, maxDate),
        )
      : view === 'months'
        ? calendarYearHasAvailableDate(month.getFullYear() + 1, minDate, maxDate)
        : calendarMonthHasAvailableDate(addCalendarMonths(month, 1), minDate, maxDate)
  const navigationUnit = view === 'years' ? t('12년') : view === 'months' ? t('해') : t('달')

  return (
    <div
      ref={rootRef}
      className={cn('ui-calendar', className)}
      role="group"
      aria-label={ariaLabel}
      aria-describedby={describedBy}
      data-disabled={disabled || undefined}
      data-mode={props.mode ?? 'single'}
      data-view={view}
      data-variant={variant}
      data-size={size}
      data-day-shape={dayShape}
      data-week-start={weekStartsOn}
      onFocusCapture={() => {
        focusWithin.current = true
      }}
      onBlurCapture={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) focusWithin.current = false
      }}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && view !== 'days') {
          event.preventDefault()
          event.stopPropagation()
          pendingFocus.current =
            view === 'years' ? '[data-calendar-year-trigger]' : '[data-calendar-month-trigger]'
          setView('days')
        }
      }}
    >
      <div className="ui-calendar-heading">
        <button
          type="button"
          className="ui-calendar-navigation"
          aria-label={t('이전 {v0}', { v0: navigationUnit })}
          disabled={disabled || !previousAvailable}
          onClick={() => changeMonth(-1)}
        >
          <ChevronLeft aria-hidden="true" />
        </button>
        <div className="ui-calendar-period">
          <button
            type="button"
            className="ui-calendar-period-button"
            data-calendar-year-trigger
            aria-label={t('연도 선택 · {v0}', { v0: yearText })}
            aria-expanded={view === 'years'}
            aria-controls={`${id}-grid`}
            disabled={disabled || !focused}
            onClick={openYears}
          >
            {yearText}
            <ChevronDown aria-hidden="true" />
          </button>
          <button
            type="button"
            className="ui-calendar-period-button"
            data-calendar-month-trigger
            aria-label={t('월 선택 · {v0}', { v0: monthText })}
            aria-expanded={view === 'months'}
            aria-controls={`${id}-grid`}
            disabled={disabled || !focused}
            onClick={openMonths}
          >
            {monthText}
            <ChevronDown aria-hidden="true" />
          </button>
        </div>
        <button
          type="button"
          className="ui-calendar-navigation"
          aria-label={t('다음 {v0}', { v0: navigationUnit })}
          disabled={disabled || !nextAvailable}
          onClick={() => changeMonth(1)}
        >
          <ChevronRight aria-hidden="true" />
        </button>
      </div>
      <span
        id={`${id}-month`}
        className={view === 'days' ? 'ui-calendar-sr-only' : 'ui-calendar-picker-title'}
        aria-live="polite"
        aria-atomic="true"
      >
        {gridTitle}
      </span>
      {view === 'days' ? (
        <div
          id={`${id}-grid`}
          role="grid"
          className="ui-calendar-grid"
          aria-labelledby={`${id}-month`}
          aria-describedby={`${id}-instructions`}
          aria-multiselectable={props.mode === 'range' || undefined}
          aria-disabled={disabled || !focused || undefined}
          onPointerLeave={() => setPreviewDate(null)}
        >
          <div role="row" className="ui-calendar-week">
            {weekdays.map((day, index) => (
              <span
                role="columnheader"
                className="ui-calendar-weekday"
                key={index}
                aria-label={fullWeekday.format(day)}
              >
                {shortWeekday.format(day)}
              </span>
            ))}
          </div>
          {Array.from({ length: days.length / 7 }, (_, week) => (
            <div role="row" className="ui-calendar-week" key={week}>
              {days.slice(week * 7, week * 7 + 7).map((date) => {
                const key = calendarDateKey(date)!
                const outside =
                  date.getMonth() !== month.getMonth() || date.getFullYear() !== month.getFullYear()
                if (outside && !showOutsideDays)
                  return (
                    <span
                      role="gridcell"
                      key={key}
                      className="ui-calendar-empty-day"
                      aria-disabled="true"
                    />
                  )
                const unavailable = disabled || !isCalendarDateInRange(date, minDate, maxDate)
                const isStart = Boolean(
                  range.start && compareCalendarDates(date, range.start) === 0,
                )
                const isEnd = Boolean(range.end && compareCalendarDates(date, range.end) === 0)
                const inRange = Boolean(
                  range.start && range.end && isCalendarDateInRange(date, range.start, range.end),
                )
                const previewing = Boolean(
                  partialRange &&
                  previewDate &&
                  visualRange.start &&
                  visualRange.end &&
                  isCalendarDateInRange(date, visualRange.start, visualRange.end),
                )
                const isSelected = props.mode === 'range' ? inRange || isStart : key === selectedKey
                const isToday = compareCalendarDates(date, today) === 0
                const metadata = dayData?.[key]
                const count =
                  metadata?.count === undefined
                    ? undefined
                    : Number.isFinite(metadata.count)
                      ? Math.max(0, Math.floor(metadata.count))
                      : 0
                const markerCount = count ?? (metadata ? 1 : 0)
                const metadataLabel = metadata
                  ? [
                      metadata.label,
                      count !== undefined && count > 0
                        ? `${dayNumber.format(count)}${variant === 'activity' ? t('회 활동') : t('개 일정')}`
                        : null,
                      metadata.completed === true
                        ? t('완료')
                        : metadata.completed === false
                          ? t('미완료')
                          : null,
                    ]
                      .filter(Boolean)
                      .join(' · ')
                  : ''
                const activityComplete = variant === 'activity' && metadata?.completed === true
                return (
                  <span
                    role="gridcell"
                    key={key}
                    aria-selected={isSelected}
                    aria-disabled={unavailable || undefined}
                    data-in-range={inRange || undefined}
                    data-range-preview={previewing || undefined}
                    data-range-start={isStart || undefined}
                    data-range-end={isEnd || undefined}
                  >
                    <button
                      type="button"
                      className="ui-calendar-day"
                      data-date={key}
                      data-selected={isSelected || undefined}
                      data-range-edge={isStart || isEnd || undefined}
                      data-today={isToday || undefined}
                      data-outside={outside || undefined}
                      data-has-data={Boolean(metadata) || undefined}
                      data-completed={metadata?.completed}
                      data-tone={metadata?.tone ?? 'neutral'}
                      aria-label={`${fullDate.format(date)}${metadataLabel ? ` · ${metadataLabel}` : ''}`}
                      title={metadataLabel || undefined}
                      aria-current={isToday ? 'date' : undefined}
                      disabled={unavailable}
                      tabIndex={!unavailable && key === dayFocusKey ? 0 : -1}
                      onFocus={() => {
                        setFocusedDate(date)
                        if (partialRange) setPreviewDate(date)
                      }}
                      onPointerEnter={() => {
                        if (partialRange && !unavailable) setPreviewDate(date)
                      }}
                      onKeyDown={(event) => handleDayKey(event, date)}
                      onClick={() => selectDay(date)}
                    >
                      <span className="ui-calendar-day-content" aria-hidden="true">
                        {activityComplete ? (
                          <span className="ui-calendar-activity-icon">
                            {metadata.icon ?? <Check />}
                          </span>
                        ) : (
                          <span className="ui-calendar-day-number">
                            {dayNumber.format(date.getDate())}
                          </span>
                        )}
                        {variant !== 'activity' && (markerCount > 0 || variant === 'schedule') ? (
                          <span className="ui-calendar-day-markers">
                            {Array.from(
                              { length: markerCount > 3 ? 1 : markerCount },
                              (_, index) => (
                                <span className="ui-calendar-event-dot" key={index} />
                              ),
                            )}
                            {markerCount > 3 ? (
                              <span className="ui-calendar-event-count">
                                {markerCount > 99 ? '99+' : dayNumber.format(markerCount)}
                              </span>
                            ) : null}
                          </span>
                        ) : null}
                      </span>
                    </button>
                  </span>
                )
              })}
            </div>
          ))}
        </div>
      ) : (
        <div
          id={`${id}-grid`}
          role="grid"
          className="ui-calendar-period-grid"
          aria-labelledby={`${id}-month`}
          aria-describedby={`${id}-instructions`}
          aria-disabled={disabled || !focused || undefined}
        >
          {Array.from({ length: view === 'months' ? 4 : Math.ceil(years.length / 3) }, (_, row) => (
            <div role="row" className="ui-calendar-period-row" key={row}>
              {Array.from(
                { length: Math.min(3, (view === 'months' ? 12 : years.length) - row * 3) },
                (_, column) => {
                  const index = row * 3 + column
                  const option = view === 'months' ? index : years[index]
                  const available =
                    view === 'months'
                      ? calendarMonthHasAvailableDate(
                          createCalendarDate(month.getFullYear(), option, 1),
                          minDate,
                          maxDate,
                        )
                      : calendarYearHasAvailableDate(option, minDate, maxDate)
                  const active =
                    view === 'months' ? option === month.getMonth() : option === month.getFullYear()
                  const focusedOption =
                    view === 'months' ? option === monthFocus : option === yearFocus
                  return (
                    <span
                      role="gridcell"
                      key={option}
                      aria-selected={active}
                      aria-disabled={!available || disabled || undefined}
                    >
                      <button
                        type="button"
                        className="ui-calendar-period-option"
                        data-month={view === 'months' ? option : undefined}
                        data-year={view === 'years' ? option : undefined}
                        data-selected={active || undefined}
                        disabled={disabled || !available}
                        tabIndex={!disabled && available && focusedOption ? 0 : -1}
                        onFocus={() =>
                          view === 'months' ? setMonthFocus(option) : setYearFocus(option)
                        }
                        onKeyDown={(event) => handlePickerKey(event, index)}
                        onClick={() =>
                          view === 'months' ? selectMonth(option) : selectYear(option)
                        }
                      >
                        {view === 'months'
                          ? monthFormatter.format(
                              createCalendarDate(month.getFullYear(), option, 1),
                            )
                          : yearNumber.format(option)}
                      </button>
                    </span>
                  )
                },
              )}
            </div>
          ))}
        </div>
      )}
      <p id={`${id}-instructions`} className="ui-calendar-instructions">
        {view === 'days'
          ? t('방향키로 이동 · Enter로 선택 · 상단 년·월로 빠르게 이동')
          : t('방향키로 이동 · Enter로 선택 · Escape로 날짜 보기')}
      </p>
      {props.mode === 'range' ? (
        <p className="ui-calendar-range-status" role="status" aria-live="polite">
          {rangeDescription}
        </p>
      ) : null}
    </div>
  )
}

